def prompts(sku):
    p=P[sku]; C=dict(CAMP[p["camp"]]); C.update(p.get("camp_over",{}))
    lock=f"Preserve the {p['noun']} from reference 1 exactly: {p['fid']}. Only the background, surface and lighting change."
    out={}
    pool=" The necklace is gathered in a compact loose pool so the whole necklace, chain included, stays in that central area; no chain runs up, down or out of the frame." if p["cat"] in ("necklace",) else ""
    out["S1"]=("Editorial advertising still life, vertical 9:16 frame. "+lock+f" CRITICAL SCALE: {p['size']}; {C['ref']} sits beside the piece, touching it, donating its size; "+RATIO[sku]+f". A dark believable contact shadow directly beneath where it touches, the soft surface dented very slightly beneath the metal. SCENE: {C['scene']}. {NEVER} The piece and the referent sit together a little below the centre of the frame, small in the frame, surrounded by generous space; the upper third and the lower quarter of the frame are the same continuous {C['colour']} surface, calm, evenly lit and softly out of focus, with no props and no hard shadows, for a headline and a price line."+pool+f" The frame is filled edge to edge by the {C['colour']} world at every corner, never a table, wall or floor of another colour; it is one continuous photograph of a single real space, with no seams, bands, stacked panels or hard straight lines crossing the frame. LIGHT: {LIGHT} Honest macro optics: depth of field only a few millimetres deep, the nearest part of the piece needle-sharp and everything slightly further away falling softly out of focus. Palette: {C['pal']}. {GRADE} No text, no logos, no watermarks, no hands, no models, no additional jewellery, {C['neg']}.")
    out["S2"]=("Editorial on-model advertising photograph, 4:5 frame, "+WORN[p["cat"]].format(noun=p["noun"],skin=p["skin"],wear=C["wear"],fabric=C["fabric"])+". "+lock+f" CRITICAL SCALE: {p['size']}, and it must read at exactly that size against the body. "+WSCALE[sku]+f" The background is {C['wall']}, generous calm space in the upper part of the frame. Soft north-window light on the skin; one small hard specular source gives the metal a crisp bright edge and every stone a single small pure-white catchlight; clear stones stay completely colourless with no orange, amber or warm glow inside them. Shallow depth of field, the piece in crisp focus, skin falling gently soft. Palette: the skin, {C['pal']}. {GRADE} No plastic skin, no heavy retouching. No text, no logos, no watermarks, no face, no extra fingers, no additional jewellery of any kind, no other rings, bracelets, necklaces or earrings.")
    one=" Show exactly one single earring from the pair, one piece only; the second earring does not appear anywhere in the frame, not even out of focus." if "pair" in p["noun"] else ""
    out["S3"]=("Extreme macro advertising photograph, 4:5 frame. "+lock+one+f" Fill most of the frame with {p['macro']}, resting on {C['fabric'] if p['camp']!='sage' else 'sage-green celadon glaze with a fine crackle'} in {C['colour']}. CRITICAL SCALE: {p['size']}; real surface texture at true scale around it, every fibre or crackle line far finer than the metal. Honest macro optics: depth of field only a few millimetres deep, a sliver needle-sharp and the rest falling to soft {C['colour']}. A dark believable contact shadow where the metal touches. {LIGHT} {NEVER} Palette: {C['pal']}. {GRADE} No text, no logos, no watermarks, no hands, no models, no additional jewellery.")
    out["S4"]=("Top-down flat lay advertising photograph, 4:5 frame: the camera looks straight down at 90 degrees onto a flat surface lying parallel to the frame, so round things stay true circles, never ellipses, and nothing recedes in perspective. "+lock+f" CRITICAL SCALE: {p['size']}; {C['ref']} lies beside the piece, touching it; "+RATIO[sku]+f". SCENE: the whole frame is {C['flat']}; no dish, no tile, no props other than the referent. The piece lies flat in the lower half of the frame, slightly off-centre, with {C['refshort']}; the whole upper half of the frame is calm, empty, evenly lit {C['colour']} with nothing in it, no props, no torn edges, no folds. Large soft diffused light from almost directly above, even across the whole frame, high-key, short soft shadows only, no light shafts, no window patterns, no dark zones; one small hard specular source gives the metal a crisp bright edge and every stone a single clean pure-white catchlight. A dark believable contact shadow beneath the piece. {NEVER} Palette: {C['pal']}. {GRADE} No text, no logos, no watermarks, no hands, no models, no additional jewellery, {C['neg']}.")
    if p["camp"]=="sage":
        out={k:v.replace("Absolutely never sand, tan, beige, cream, grey or golden backgrounds.","Absolutely never sand, tan, beige, cream or golden backgrounds.") for k,v in out.items()}
    return out
if __name__=="__main__":
    ALL={s:prompts(s) for s in P}
    json.dump(ALL,open('ladder.json','w'),indent=1)
    print(len(ALL), sum(len(v) for v in ALL.values()))
    print(ALL["E14776S"]["S2"][:600])
